class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        def run(is_max):
            n = len(nums); st = []; h = [0]*n; ans = 0
            for i, x in enumerate(nums):
                while st and (nums[st[-1]] <= x if is_max else nums[st[-1]] >= x):
                    st.pop()
                j = st[-1] if st else -1
                h[i] = (h[j] if j >= 0 else 0) + x*(i - j)
                ans += h[i] - (h[i-k] if i >= k else 0)
                st.append(i)
            return ans
        return run(True) + run(False)

