class Solution {
public:
    long long minMaxSubarraySum(vector<int>& nums, int k) {
        auto run = [&](bool isMax) {
            int n = nums.size(); vector<long long> h(n); vector<int> st; long long ans = 0;
            for (int i = 0; i < n; i++) {
                while (!st.empty() && (isMax ? nums[st.back()] <= nums[i] : nums[st.back()] >= nums[i])) st.pop_back();
                int j = st.empty() ? -1 : st.back();
                h[i] = (j >= 0 ? h[j] : 0) + (long long)nums[i] * (i - j);
                ans += h[i] - (i >= k ? h[i-k] : 0);
                st.push_back(i);
            }
            return ans;
        };
        return run(true) + run(false);
    }
};

