class Solution {
    public long minMaxSubarraySum(int[] nums, int k) {
        return run(nums, k, true) + run(nums, k, false);
    }
    private long run(int[] nums, int k, boolean isMax) {
        int n = nums.length; long[] h = new long[n]; Deque<Integer> st = new ArrayDeque<>(); long ans = 0;
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && (isMax ? nums[st.peek()] <= nums[i] : nums[st.peek()] >= nums[i])) st.pop();
            int j = st.isEmpty() ? -1 : st.peek();
            h[i] = (j >= 0 ? h[j] : 0) + (long) nums[i] * (i - j);
            ans += h[i] - (i >= k ? h[i-k] : 0);
            st.push(i);
        }
        return ans;
    }
}

