var minMaxSubarraySum = function(nums, k) {
    const run = (isMax) => {
        const n = nums.length, st = [], h = new Array(n).fill(0);
        let ans = 0;
        for (let i = 0; i < n; i++) {
            while (st.length && (isMax ? nums[st[st.length-1]] <= nums[i] : nums[st[st.length-1]] >= nums[i])) st.pop();
            const j = st.length ? st[st.length-1] : -1;
            h[i] = (j >= 0 ? h[j] : 0) + nums[i] * (i - j);
            ans += h[i] - (i >= k ? h[i-k] : 0);
            st.push(i);
        }
        return ans;
    };
    return run(true) + run(false);
};
